<?php
namespace Tests\Feature;
use App\Models\{AttendanceEvent,AttendanceParticipant,AttendanceRecord,Empleado,TrainingEvaluation,TrainingQuestion,TrainingSession,TrainingTopic,User}; use App\Services\{TrainingEvaluationScoringService,TrainingEvaluationService}; use Illuminate\Foundation\Testing\DatabaseTransactions; use Illuminate\Support\Str; use Tests\TestCase;
class TrainingEvaluationFlowTest extends TestCase{use DatabaseTransactions;public function test_published_snapshot_is_scored_server_side_and_creates_no_reinforcement_when_passed():void{$user=User::whereNotNull('company_id')->first();if(!$user)$this->markTestSkipped('Sin usuario empresarial.');$employee=Empleado::where('company_id',$user->company_id)->first();if(!$employee)$this->markTestSkipped('Sin empleado empresarial.');$topic=TrainingTopic::create(['company_id'=>$user->company_id,'code'=>'TEST-'.Str::random(8),'name'=>'Tema prueba','description'=>'Prueba','training_type'=>'training','general_objective'=>'Validar','is_active'=>true,'created_by'=>$user->id]);$session=TrainingSession::create(['company_id'=>$user->company_id,'training_topic_id'=>$topic->id,'uuid'=>(string)Str::uuid(),'title'=>'Sesión prueba','training_type'=>'training','session_purpose'=>'regular','scheduled_start_at'=>now(),'scheduled_end_at'=>now()->addHour(),'planned_duration_minutes'=>60,'modality'=>'presential','instructor_type'=>'internal','instructor_employee_id'=>$employee->id,'status'=>'closed','audience_type'=>'specific_employees','specific_employee_ids'=>[$employee->id],'requires_attendance'=>true,'requires_signature'=>false,'requires_material'=>false,'requires_execution_report'=>false,'created_by'=>$user->id]);$event=AttendanceEvent::create(['company_id'=>$user->company_id,'uuid'=>(string)Str::uuid(),'attendable_type'=>'training_session','attendable_id'=>$session->id,'title'=>'Prueba','event_type'=>'training_session','starts_at'=>now(),'ends_at'=>now()->addHour(),'attendance_opens_at'=>now()->subMinute(),'attendance_closes_at'=>now()->addHour(),'status'=>'closed','created_by'=>$user->id]);$session->update(['attendance_event_id'=>$event->id]);$participant=$event->participants()->create(['uuid'=>(string)Str::uuid(),'participant_type'=>'employee','employee_id'=>$employee->id,'name_snapshot'=>$employee->nombre_completo,'expected'=>true]);$event->records()->create(['uuid'=>(string)Str::uuid(),'attendance_participant_id'=>$participant->id,'status'=>'confirmed','verification_method'=>'manual','verification_code'=>Str::random(32)]);$question=TrainingQuestion::create(['company_id'=>$user->company_id,'training_topic_id'=>$topic->id,'question_text'=>'Pregunta segura','question_type'=>'single_choice','default_points'=>1,'is_active'=>true,'created_by'=>$user->id]);$right=$question->options()->create(['option_text'=>'Correcta','is_correct'=>true,'sort_order'=>1]);$question->options()->create(['option_text'=>'Incorrecta','is_correct'=>false,'sort_order'=>2]);$evaluation=TrainingEvaluation::create(['company_id'=>$user->company_id,'training_topic_id'=>$topic->id,'training_session_id'=>$session->id,'uuid'=>(string)Str::uuid(),'title'=>'Evaluación','instructions'=>'Responda','evaluation_type'=>'knowledge_quiz','passing_score'=>80,'maximum_attempts'=>2,'requires_reinforcement'=>true,'requires_confirmed_attendance'=>true,'status'=>'draft','created_by'=>$user->id]);$service=app(TrainingEvaluationService::class);$links=$service->publish($evaluation,[$question->id],$user->id);$this->assertCount(1,$links);$access=$evaluation->accesses()->first();$attempt=$service->start($evaluation->fresh(),$access);$snapshot=$evaluation->questions()->first();$snapshotRight=$snapshot->options()->where('option_text','Correcta')->first();$graded=$service->submit($attempt,[$snapshot->id=>[$snapshotRight->id]],[],app(TrainingEvaluationScoringService::class),app(\App\Services\TrainingAiGradingService::class));$this->assertSame('passed',$graded->result);$this->assertEquals(100.0,$graded->percentage_score);$this->assertFalse($graded->reinforcement??false);$question->update(['question_text'=>'Pregunta cambiada']);$this->assertSame('Pregunta segura',$snapshot->fresh()->question_text);}}
